'use client'

// Generated by SpecForge from "Shop" (1.0.0). Safe to edit.
import { useState } from 'react'
import Button from '@mui/material/Button'
import Grid from '@mui/material/Grid'
import { useTranslations } from 'next-intl'
import { ApiError } from '@/lib/api/client'
import { useConstraints } from '@/lib/reference'
import { Modal } from '@/components/modal'
import { TextAreaField, TextField } from '@/components/form-fields'
import { useToast } from '@/components/toast-provider'
import { useSaveCustomer } from './api'
import type { Customer, CustomerInput } from './types'

interface FormState {
  email: string
  fullName: string
  notes: string
}

export function CustomerFormModal({ row, onClose }: { row: Customer | null; onClose: () => void }) {
  const t = useTranslations('shop')
  const tCommon = useTranslations('common')
  const field = useConstraints('shopCustomer')
  const toast = useToast()
  const save = useSaveCustomer()
  const [form, setForm] = useState<FormState>({
    email: row?.email ?? '',
    fullName: row?.fullName ?? '',
    notes: row?.notes ?? '',
  })
  const errors = save.error instanceof ApiError ? save.error.fieldErrors : {}
  const set =
    <K extends keyof FormState>(key: K) =>
    (value: FormState[K]) =>
      setForm(f => ({ ...f, [key]: value }))

  const submit = () => {
    const input: CustomerInput = {
      email: form.email || null,
      fullName: form.fullName || null,
      notes: form.notes || null,
    }
    save.mutate(
      { id: row?.id, input },
      {
        onSuccess: () => {
          toast.success(row ? tCommon('saved') : tCommon('created'))
          onClose()
        },
        onError: error => {
          if (!(error instanceof ApiError) || Object.keys(error.fieldErrors).length === 0) {
            toast.error(error instanceof ApiError ? error.message : tCommon('unknownError'))
          }
        },
      }
    )
  }

  return (
    <Modal
      open
      title={row ? t('customer.edit') : t('customer.new')}
      onClose={onClose}
      busy={save.isPending}
      onSubmit={submit}
      footer={
        <>
          <Button variant="outlined" color="inherit" onClick={onClose} disabled={save.isPending}>
            {tCommon('cancel')}
          </Button>
          <Button type="submit" variant="contained" disabled={save.isPending}>
            {save.isPending ? tCommon('saving') : tCommon('save')}
          </Button>
        </>
      }
    >
      <Grid container spacing={2}>
        <Grid size={{ xs: 12, md: 6 }}>
          <TextField
            label={t('customer.fields.email')}
            value={form.email}
            onChange={set('email')}
            {...field('email')}
            error={errors.email}
          />
        </Grid>
        <Grid size={{ xs: 12, md: 6 }}>
          <TextField
            label={t('customer.fields.fullName')}
            value={form.fullName}
            onChange={set('fullName')}
            {...field('fullName')}
            error={errors.fullName}
          />
        </Grid>
        <Grid size={{ xs: 12 }}>
          <TextAreaField
            label={t('customer.fields.notes')}
            value={form.notes}
            onChange={set('notes')}
            required={field('notes').required}
            maxLength={field('notes').maxLength}
            error={errors.notes}
          />
        </Grid>
      </Grid>
    </Modal>
  )
}
